import{z as s,x as o,o as B,c as d,q as i,j as t,D as a,d as e,s as r,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"数据配方的消融设计","description":"","frontmatter":{"title":"数据配方的消融设计","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-ablation-design.md","filePath":"llm/synthetic-ablation-design.md","lastUpdated":1791413859000}'),D={name:"llm/synthetic-ablation-design.md"};function C(m,E,p,h,F,c){const l=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=i('<h1 id="数据配方的消融设计" tabindex="-1">数据配方的消融设计 <a class="header-anchor" href="#数据配方的消融设计" aria-label="Permalink to &quot;数据配方的消融设计&quot;">​</a></h1><div class="epigraph"><p>配方有几十个旋钮，直觉一个都不灵：数据工程的因果结论，只能从控制变量的实验里来，不能从复盘的感觉里来。</p><footer>—— 据 Xie 等 DoReMi；Chen 等 RegMix；本站小模型代理实验课整理</footer></div><p><a href="/llm/synthetic-eval-sets">上一课</a>立了评测的纪律——有了可信的尺子，才谈得上归因。本课写归因本身：配方由过滤阈值、去重档位、配比、演化轮数、难度窗等几十个旋钮组成，哪个旋钮真正在起作用，唯一的来源是设计好的消融。<a href="/llm/proxy-model-experiments">小模型代理实验</a>讲过代理的坑，<a href="/llm/doremi">DoReMi</a>与 <a href="/llm/regmix">RegMix</a>给过配比搜索的两种自动化。本课把它们收成一套对合成管线通用的实验协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成管线的消融比模型结构难，难在环节耦合：过滤器变了，配比的最优点就变；配比变了，难度窗的最优位置也变。单因素实验在这种耦合下会给出误导性的「不显著」——单独动过滤器看不出效果，是因为它的效果要靠配比配合才能显形。另一类错误是把「数据更多总没坏」当公理：合成数据的增量可能负迁移（风格污染、难度错位），「加不加」必须是实验问题。最贵的错误是直接在目标规模上做探索：一次全量训练的成本足以覆盖几十次代理实验，没有协议的团队会把预算烧在「试一下」上。<span class="marginnote">术语翻译：「消融」（ablation）就是每次只拧动或摘掉配方的一个部件，看结果掉多少，从而判断这个部件贡献了什么——这个词借自生物学里切除器官研究功能的老办法。它回答的是「因果上谁在起作用」，不是「最终配方好不好」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议四件。旋钮清单与耦合图：把配方的旋钮列全，标出已知耦合（过滤器-配比、配比-难度窗、演化轮数-去重阈值），消融设计从耦合对里取，不从清单里随机抽。代理先行：小模型加小数据跑方向；代理的失真有已知方向——太稳出假阴性，数据制度不同出假阳性，方向性结论至少在两个规模复验。单因素与因子网格并用：初筛用单因素，每轮只动一个旋钮、其余冻结在当前定版；耦合可疑的对子用二因子网格（两旋钮各取两档），看交互项是否存在。方差纪律：固定评测网格与训练种子集合，报告均值加区间，<a href="/llm/eval-variance-seed">评测的种子方差</a>课的口径直接沿用；单点差异不进结论。</p>',7)),(B(),t(n,null,{default:a(()=>[r(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20KNOB%5B%22%E6%97%8B%E9%92%AE%E6%B8%85%E5%8D%95%E4%B8%8E%E8%80%A6%E5%90%88%E5%9B%BE%22%5D%20--%3E%20PROXY%5B%22%E4%BB%A3%E7%90%86%E5%AE%9E%E9%AA%8C%EF%BC%9A%E6%96%B9%E5%90%91%E5%88%9D%E7%AD%9B%22%5D%0A%20%20PROXY%20--%3E%20SCALE%7B%22%E4%B8%A4%E8%A7%84%E6%A8%A1%E6%96%B9%E5%90%91%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20SCALE%20--%3E%7C%E5%90%A6%7C%20FIX%5B%22%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%88%B6%E5%BA%A6%E5%B7%AE%EF%BC%8C%E9%87%8D%E8%AE%BE%E4%BB%A3%E7%90%86%22%5D%0A%20%20SCALE%20--%3E%7C%E6%98%AF%7C%20OFAT%5B%22%E5%8D%95%E5%9B%A0%E7%B4%A0%E7%AD%9B%E9%80%89%22%5D%0A%20%20OFAT%20--%3E%20PAIR%7B%22%E5%AD%98%E5%9C%A8%E8%80%A6%E5%90%88%E5%AB%8C%E7%96%91%EF%BC%9F%22%7D%0A%20%20PAIR%20--%3E%7C%E6%98%AF%7C%20GRID%5B%22%E4%BA%8C%E5%9B%A0%E5%AD%90%E7%BD%91%E6%A0%BC%E7%9C%8B%E4%BA%A4%E4%BA%92%E9%A1%B9%22%5D%0A%20%20PAIR%20--%3E%7C%E5%90%A6%7C%20VERDICT%5B%22%E5%AE%9A%E7%89%88%EF%BC%9A%E6%97%8B%E9%92%AE%E5%86%99%E8%BF%9B%E9%85%8D%E6%96%B9%E7%89%88%E6%9C%AC%22%5D%0A%20%20GRID%20--%3E%20VERDICT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"为什么单因素会漏：管线是一串重加权的复合函数，每个旋钮的效果都以其余旋钮为条件——统计上这是交互项，工程上是「换了过滤器就得重新调配比」的日常经验。二因子网格不是全因子：全因子在十几个旋钮下不可行，按耦合图选对子才是可执行的折衷。代理外推的机制边界在代理实验课已立：合成数据的制度差通常表现为「代理学合成的效率高于目标模型」，方向反转的高发区是质量过滤档位——代理模型上「更严过滤更好」，目标规模上未必，因为小模型本来就容不下噪声。配比搜索的自动化（回归面拟合或 DRO）不取消消融，只改变它的对象：自动搜索给你最优点，消融回答「为什么是最优、换了教师还成不成立」。",-1)),(B(),t(n,null,{default:a(()=>[r(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%8F%AA%E5%8A%A8%E8%BF%87%E6%BB%A4%E5%99%A8%2C%20%E9%85%8D%E6%AF%94%E5%86%BB%E7%BB%93%22%5D%20--%3E%20R1%5B%22%E8%AF%BB%E6%95%B0%E8%BF%91%E9%9B%B6%3A%20%E5%88%A4%E4%B8%BA%E4%B8%8D%E6%98%BE%E8%91%97%22%5D%0A%20%20B%5B%22%E5%8F%AA%E8%B0%83%E9%85%8D%E6%AF%94%2C%20%E8%BF%87%E6%BB%A4%E5%99%A8%E5%86%BB%E7%BB%93%22%5D%20--%3E%20R2%5B%22%E8%AF%BB%E6%95%B0%E5%B0%8F%E5%B9%85%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20G%5B%22%E4%BA%8C%E5%9B%A0%E5%AD%90%E7%BD%91%E6%A0%BC%3A%20%E4%B8%A5%2F%E6%9D%BE%20%C3%97%205%25%2F20%25%2C%20%E5%85%B1%204%20%E6%A0%BC%22%5D%20--%3E%20R3%5B%22%E4%BA%A4%E4%BA%92%E9%A1%B9%E6%98%BE%E5%BD%A2%3A%20%E4%B8%A5%E8%BF%87%E6%BB%A4%E5%8F%AA%E5%9C%A8%E6%B5%93%E9%85%8D%E6%AF%94%E4%B8%8B%E6%B6%A8%E5%88%86%22%5D%0A%20%20R3%20--%3E%20C%5B%22%E7%BB%93%E8%AE%BA%3A%20%E5%B9%B3%E5%B9%B3%E6%97%A0%E5%A5%87%E7%9A%84%E6%97%8B%E9%92%AE%E5%8F%AF%E8%83%BD%E6%98%AF%E5%85%B3%E9%94%AE%E8%80%A6%E5%90%88%E4%BB%B6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">配方要版本化三件套：数据版本、生成器版本、过滤器版本。少了任何一件，三个月后的你就无法解释「那次涨分」——数据实验的复现成本集中在环境重建，不在重训本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>消融结论的有效期绑定教师与基座版本：换代即作废，能继承的只有结构与方向。代理规模太小会整个脱离数据制度——比如目标规模的退火阶段在小代理上不存在——此时方向结论直接无效，不要硬推。评测网格要覆盖配方声称的能力域，用错网格的消融会系统性偏向某类旋钮：只测平均分会偏向通用旋钮、掩盖域内收益。最后，消融不能替代监控：定版之后，配方的每个旋钮仍要有读数（过滤率、桶占比、难度分布），漂移要从读数发现，不是从分数倒推。<span class="marginnote">常见误区：初学者容易把一次实验里的单点分差当成结论，比如「+0.4 分，说明这个过滤器有效」。种子与评测噪声常就有半个点的抖动，正确做法是固定种子集合报均值加区间，落在区间内的差异一律不进结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>旋钮清单加耦合图先行，消融从耦合对取，不随机抽。</li><li>代理跑方向，两规模复验；制度差高发在过滤档位。</li><li>单因素初筛，耦合对二因子网格看交互项。</li><li>均值加区间进结论，单点差异不进。</li><li>配方版本化三件套：数据、生成器、过滤器版本。</li><li>出处：Xie 等 DoReMi 2023；Chen 等 RegMix 2024；本站代理实验与配比定律课。</li></ul>',5))])}const u=s(D,[["render",C]]);export{_ as __pageData,u as default};
